select a.wi_name as 'WI_NAME', b.FACILITY as fac_name,a.product as PRODUCT,concat(concat(a.PRODUCT,'-'),b.FACILITY) as fac_code,  concat(concat(concat(concat('Request Type: ',a.REQUEST_TYPE),'</br>'),'Currency: ') ,a.CURRENCY) as req_ccy,a.DETAILED_FAC_PURPOSE as purpose,a.TENOR_IN_MONTHS as tenure, a.P_EFFEC_INT_RATE as int_rate, a.EQUI_AMT_IN_HOME_CURR as last_approved,a.CURRENT_OUTSTANDING as current_exposure,a.CURRENCY as amount, case  when a.REQUEST_TYPE!= 'New' then 'NA'  end as  limit_now, '' as expiry , '' as review from  NG_CLOS_Borrower_existingLoans a, NGM_CLOS_FACILITY b  where a.PRODUCT=b.FACILITY_CODE and a.wi_name = '#wi_name#'